<?php $collection=$a->badges->forUser((int)$badgeUser);if($collection): ?><div class="badge-collection" aria-label="<?= t('Community badges') ?>"><?php foreach($collection as $badge): ?><a class="recognition-token" data-badge-tone="<?= e($badge['tone']) ?>" href="<?= e(url('badges')) ?>" title="<?= e($badge['description']) ?>"><?= icon($badge['symbol']) ?><span><?= e($badge['name']) ?></span></a><?php endforeach ?></div><?php endif ?>